interface SagaStepPayload {
  amount: number
  fromAccountId?: string
  toAccountId?: string
}

interface SagaStepRow {
  id: string
  sagaId: string
  step: string
  idempotencyKey: string // `${sagaId}:${step}`
  status: "ok" | "failed"
  createdAt: Date
}

interface ActiveSaga {
  sagaId: string
  plannedSteps: string[]
  payloadFor(step: string): SagaStepPayload
}

@Injectable()
export class WalletSagaOrchestrator {
  constructor(
    private readonly walletService: WalletServiceClient, // HTTP client to the separate wallet-service
    private readonly sagaStepRepository: Repository<SagaStepRow>,
  ) {}

  /**
   * Executes a single saga step (e.g. "debit-sender", "credit-receiver")
   * by calling wallet-service, then records the outcome for audit/recovery.
   */
  async executeStep(sagaId: string, step: string, payload: SagaStepPayload): Promise<void> {
    const idempotencyKey = `${sagaId}:${step}`

    try {
      // The money-moving side effect. This is what actually changes wallet balances.
      await this.walletService.applyStep(idempotencyKey, payload)

      // Audit write happens only AFTER the HTTP call has already returned.
      // If the process dies between the line above and this insert, the
      // side effect landed but there is zero durable evidence it ran.
      await this.sagaStepRepository.insert({
        sagaId,
        step,
        idempotencyKey,
        status: "ok",
        createdAt: new Date(),
      })
    } catch (error) {
      await this.sagaStepRepository.insert({
        sagaId,
        step,
        idempotencyKey,
        status: "failed",
        createdAt: new Date(),
      })
      throw error
    }
  }

  /**
   * Runs on orchestrator restart to find work that was interrupted by a crash.
   */
  async recoveryScan(): Promise<void> {
    const recordedSteps = await this.sagaStepRepository.find()
    const recordedKeys = new Set(recordedSteps.map((row) => row.idempotencyKey))

    for (const saga of await this.loadActiveSagas()) {
      for (const step of saga.plannedSteps) {
        const idempotencyKey = `${saga.sagaId}:${step}`

        // Only "ok" and "failed" rows are ever written, so a step that
        // crashed between the wallet-service call and the audit insert
        // has no row at all. This branch cannot tell "never attempted"
        // apart from "attempted, side effect landed, crashed before logging" -
        // it just silently re-runs the step as if it never happened.
        if (!recordedKeys.has(idempotencyKey)) {
          await this.executeStep(saga.sagaId, step, saga.payloadFor(step))
        }
      }
    }
  }

  private async loadActiveSagas(): Promise<ActiveSaga[]> {
    // Loads sagas that haven't reached a terminal (all-steps-ok or compensated) state.
    return []
  }
}
